import zipfile, pickle, io, sys, hashlib

class Dummy:
    def __init__(self, *args, **kwargs):
        pass
    def __repr__(self):
        return '<Dummy>'

# Custom unpickler
class MyUnpickler(pickle.Unpickler):
    def find_class(self, module, name):
        # Return Dummy for any unknown class
        try:
            return super().find_class(module, name)
        except Exception:
            return Dummy

z = zipfile.ZipFile('/challenge/attachment/maze.pt')
